#define R iResolution.xy
#define rot(n) mat2(cos(n),-sin(n),sin(n),cos(n))
#define rand(v) fract(sin(sin(v.x*99.99)*99.99+v.y*99.99)*99.99)

float scene(vec2 p, vec2 seed)
{
    float t = iTime+rand(seed)*99.99;

    float acc=0.;
    float td,ld;
    vec3 ro=vec3(p,-1),
         rd=-normalize(ro),
         po=ro;

    for(float i=1.; i<99.; i++){
        po = ro+rd*td;

        po.z -= 2.;
        po.xz *= rot(t);
        po.zy *= rot(t);

        ld = length(vec2(abs(length(po.xy)-.5),po.z))-.25;
        td += max(.01,ld);

        acc += exp(-ld*64.)/(i*i);
        if (td>1e3){
            break;
        }
    }

    return acc;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.*(fragCoord-R*.5)/R.y;

    uv.x -= iTime*.25;
    vec2 seed = floor(uv);
    uv = fract(uv)*2.-1.;

    uv += (vec2(rand(fragCoord.xx),rand(fragCoord.yy))-.5)*.35;

    float val = round(scene(uv*.5, seed));

    fragColor = vec4(vec3(val),1.0);
}
